package com.simon.offlinebms;
import java.time.Instant;
import java.util.*;
/** A self-contained report: inline CSS/SVG, with no scripts, external fonts or requests. */
public final class OfflineReport {
    private static String e(String value){return value.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&#39;");}
    private static String f(double value,int digits){return Double.isFinite(value)?String.format(Locale.UK,"%."+digits+"f",value):"—";}
    public static String create(Reading r,ProfileStore.Profile profile,EnergyStats stats,List<double[]> rows,long range){
        if(r.isDemo)throw new IllegalArgumentException("Demo report is not available");String name=profile==null?r.device:profile.name;StringBuilder b=new StringBuilder("<!doctype html><html lang='en'><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Battery report</title><style>body{font:16px system-ui,sans-serif;background:#f3f5f3;color:#18312e;max-width:920px;margin:0 auto;padding:24px}h1{font-size:32px}h2{font-size:20px;margin-top:30px}.sub{color:#627b76}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px}.card{background:white;border-radius:18px;padding:18px}.value{font-size:28px;font-weight:600;color:#17785f}table{width:100%;border-collapse:collapse;background:white}td,th{text-align:left;padding:12px;border-bottom:1px solid #e1e9e5}svg{width:100%;height:auto;background:white;border-radius:16px}.note{white-space:pre-wrap}@media print{body{padding:0;background:white}.card{border:1px solid #dbe4de}h2{break-after:avoid}tr{break-inside:avoid}}</style><body><p class='sub'>OFFLINE BMS • LOCAL BATTERY REPORT</p><h1>");
        b.append(e(name)).append("</h1><p class='sub'>Battery ").append(e(r.address)).append("<br>Reading ").append(Instant.ofEpochMilli(r.timestamp)).append("<br>Report created ").append(Instant.now()).append("</p><div class='grid'>");
        metric(b,"State of charge",r.basic.soc+"%");metric(b,"Pack voltage",f(r.basic.voltage,2)+" V");metric(b,"Current",f(r.basic.current,2)+" A");metric(b,"Power",f(r.basic.power(),0)+" W");metric(b,"Cell spread",f(r.deltaMv(),0)+" mV");metric(b,"Remaining",f(r.basic.remainingAh,1)+" Ah");b.append("</div><p class='sub'>Positive current/power means charging; negative means discharging. Values are the last available BMS reading, not a battery health certificate.</p><h2>Recorded history</h2><p>Selected window: ").append(f(range/3600000.0,0)).append(" hours. ").append(stats.samples).append(" samples; ").append(f(stats.observedMs/3600000.0,2)).append(" hours of measured intervals.</p><div class='grid'>");metric(b,"Charged",f(stats.chargeWh/1000,3)+" kWh");metric(b,"Used",f(stats.dischargeWh/1000,3)+" kWh");metric(b,"Charge in",f(stats.chargeAh,2)+" Ah");metric(b,"Charge out",f(stats.dischargeAh,2)+" Ah");b.append("</div><p class='sub'>Intervals longer than 90 seconds and changes of session are excluded from integration. Missing data is not treated as zero usage.</p>");
        b.append("<h2>State of charge (%)</h2>");graph(b,rows,1,"State of charge history");b.append("<h2>Power (W)</h2>");graph(b,rows,2,"Power history");b.append("<h2>Individual cells</h2><table><tr><th>Cell</th><th>Voltage</th><th>Status</th></tr>");for(int i=0;i<r.cells.length;i++)b.append("<tr><td>").append(i+1).append("</td><td>").append(f(r.cells[i],3)).append(" V</td><td>").append((r.basic.balanceMask&(1L<<i))!=0?"Balancing":"—").append("</td></tr>");b.append("</table><h2>Temperature &amp; status</h2><p>");for(int i=0;i<r.basic.temperatures.length;i++)b.append("T").append(i+1).append(": ").append(f(r.basic.temperatures[i],1)).append(" °C<br>");b.append("Charge MOSFET: ").append(r.basic.chargeEnabled()?"enabled":"disabled").append("<br>Discharge MOSFET: ").append(r.basic.dischargeEnabled()?"enabled":"disabled").append("<br>Cycles: ").append(r.basic.cycles).append("<br>Firmware: ").append(e(r.basic.versionText())).append("</p><p>");String[] protections=r.protectionLabels();if(protections.length==0)b.append("No active BMS protection flags reported.");for(String s:protections)b.append(e(s)).append("<br>");b.append("</p>");if(profile!=null)b.append("<h2>Profile notes</h2><p>").append(e(profile.chemistry)).append(" • reserve ").append(f(profile.reservePercent,0)).append("%</p><p class='note'>").append(e(profile.notes)).append("</p>");return b.append("<p class='sub'>Generated entirely on the phone. This report contains no passwords or external resources.</p></body></html>").toString();
    }
    private static void metric(StringBuilder b,String title,String value){b.append("<div class='card'><div class='sub'>").append(e(title)).append("</div><div class='value'>").append(e(value)).append("</div></div>");}
    private static void graph(StringBuilder b,List<double[]> rows,int metric,String title){if(rows.isEmpty()){b.append("<p class='sub'>No saved readings in this window.</p>");return;}double low=Double.POSITIVE_INFINITY,high=Double.NEGATIVE_INFINITY;for(double[] row:rows){low=Math.min(low,row[metric]);high=Math.max(high,row[metric]);}if(high==low){low-=1;high+=1;}double start=rows.get(0)[0],end=Math.max(start+1,rows.get(rows.size()-1)[0]);b.append("<svg viewBox='0 0 720 230' role='img' aria-label='").append(e(title)).append("'><text x='12' y='23' fill='#627b76'>").append(f(high,1)).append("</text><text x='12' y='190' fill='#627b76'>").append(f(low,1)).append("</text><path fill='none' stroke='#17785f' stroke-width='3' d='");double prev=0,gap=Math.max(90000,(end-start)/700*3);boolean first=true;for(double[] row:rows){b.append(first||row[0]-prev>gap?"M":"L").append(f(60+640*(row[0]-start)/(end-start),2)).append(' ').append(f(190-160*(row[metric]-low)/(high-low),2)).append(' ');prev=row[0];first=false;}b.append("'/><text x='60' y='218' fill='#627b76'>").append(Instant.ofEpochMilli((long)start)).append("</text></svg>");}
}
